// =====================================================
// INA226 REGISTER READ
// =====================================================

bool readINA226Register(
  uint8_t reg,
  int16_t &value
) {

  Wire.beginTransmission(
    INA226_ADDRESS
  );

  Wire.write(
    reg
  );

  if (
    Wire.endTransmission(
      false
    ) != 0
  ) {

    return false;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (
    Wire.available() <
    2
  ) {

    return false;
  }

  uint16_t raw =
    (
      (uint16_t)Wire.read()
      <<
      8
    )
    |
    Wire.read();

  value =
    (int16_t)raw;

  return true;
}


// =====================================================
// SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(
  float &millivolts
) {

  int16_t raw;

  if (
    !readINA226Register(
      0x01,
      raw
    )
  ) {

    return false;
  }

  millivolts =
    raw
    *
    INA226_SHUNT_LSB_V
    *
    1000.0;

  return true;
}


// =====================================================
// SORT ADC VALUES
// =====================================================

void sortValues(
  uint32_t values[],
  int count
) {

  for (
    int i = 0;
    i < count - 1;
    i++
  ) {

    for (
      int j = i + 1;
      j < count;
      j++
    ) {

      if (
        values[j] <
        values[i]
      ) {

        uint32_t temp =
          values[i];

        values[i] =
          values[j];

        values[j] =
          temp;
      }
    }
  }
}


// =====================================================
// READ BATTERY VOLTAGE
// =====================================================

float readBatteryVoltage() {

  const int SAMPLE_COUNT =
    64;

  uint32_t samples[
    SAMPLE_COUNT
  ];

  for (
    int i = 0;
    i < SAMPLE_COUNT;
    i++
  ) {

    samples[i] =
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(
      150
    );
  }

  sortValues(
    samples,
    SAMPLE_COUNT
  );

  uint32_t total =
    0;

  int count =
    0;

  // Reject lowest 12 and
  // highest 12 samples.

  for (
    int i = 12;
    i < 52;
    i++
  ) {

    total +=
      samples[i];

    count++;
  }

  float sensorVoltage =
    (
      total /
      (float)count
    )
    /
    1000.0;

  return
    sensorVoltage
    *
    VOLTAGE_DIVIDER_RATIO
    *
    VOLTAGE_CALIBRATION;
}


