}


// =====================================================
// LOAD BATTERY STATE
// =====================================================

void loadBatteryState() {

  preferences.begin(
    "battery",
    true
  );

  socSynchronized =
    preferences.getBool(
      "synced",
      false
    );

  remainingAh =
    preferences.getFloat(
      "remaining",
      0.0
    );

  preferences.end();

  if (
    socSynchronized
  ) {

    remainingAh =
      constrain(
        remainingAh,
        0.0,
        BATTERY_CAPACITY_AH
      );
  }
}


// =====================================================
// SET BATTERY FULL
// =====================================================

void setBatteryFull() {

  socSynchronized =
    true;

  remainingAh =
    BATTERY_CAPACITY_AH;

  sessionUsedAh =
    0.0;

  sessionChargedAh =
    0.0;

  peakDischarge_A =
    0.0;

  peakCharge_A =
    0.0;

  averageDischarge_A =
    0.0;

  sessionStartMillis =
    millis();

  saveBatteryState();
}


// =====================================================
