// =====================================================

void resetSession() {

  sessionUsedAh =
    0.0;

  sessionChargedAh =
    0.0;

  peakDischarge_A =
    0.0;

  peakCharge_A =
    0.0;

  averageDischarge_A =
    0.0;

  sessionStartMillis =
    millis();
}


// =====================================================
// SOC
// =====================================================

float getSOC() {

  if (
    !socSynchronized
  ) {

    return 0.0;
  }

  return
    (
      remainingAh
      /
      BATTERY_CAPACITY_AH
    )
    *
    100.0;
}


// =====================================================
// STATUS
// =====================================================

String batteryStatus() {

  if (
    filteredCurrent_A >
    0.10
  ) {

    return
      "DISCHARGING";
  }

  if (
    filteredCurrent_A <
    -0.10
  ) {

    return
      "CHARGING";
  }

  return
    "IDLE";
}


// =====================================================
// TIME TO EMPTY
// =====================================================

float getTimeToEmptyHours() {

  if (
    !socSynchronized
  ) {

    return -1;
  }

  if (
    averageDischarge_A <
    0.10
  ) {

    return -1;
  }

  return
    remainingAh
    /
    averageDischarge_A;
}


// =====================================================
// UPDATE BATTERY MONITOR
// =====================================================

void updateBatteryMonitor() {

  unsigned long now =
    millis();

  if (
    now -
    lastSampleMillis
    <
    SAMPLE_INTERVAL_MS
  ) {

    return;
  }

  unsigned long elapsedMs =
    now -
    lastSampleMillis;

  lastSampleMillis =
    now;


  // ===================================================
  // BATTERY VOLTAGE
  // ===================================================

  rawBatteryVoltage =
    readBatteryVoltage();

  if (
    batteryVoltage ==
    0.0
  ) {

    batteryVoltage =
      rawBatteryVoltage;
  }

  else {

    batteryVoltage =
      (
        0.10
        *
        rawBatteryVoltage
      )
      +
      (
        0.90
        *
        batteryVoltage
      );
  }


  // ===================================================
  // CURRENT
  // ===================================================

  float newShunt;

  if (
    readShuntVoltage(
      newShunt
    )
  ) {

    shuntVoltage_mV =
      newShunt;

    current_A =
      (
        shuntVoltage_mV
        /
        1000.0
      )
      /
      SHUNT_OHMS;


    // -------------------------------------------------
    // ZERO DEADBAND
    // -------------------------------------------------

    if (
      fabs(
        current_A
      )
      <
      CURRENT_DEADBAND_A
    ) {

      current_A =
        0.0;
    }


    // -------------------------------------------------
    // FILTER DISPLAY CURRENT
    // -------------------------------------------------

    filteredCurrent_A =
      (
        0.25
        *
        current_A
      )
      +
      (
        0.75
        *
        filteredCurrent_A
      );


    // =================================================
    // DISCHARGE
    // =================================================

    if (
      current_A >
      0.0
    ) {

      if (
        current_A >
        peakDischarge_A
      ) {

        peakDischarge_A =
          current_A;
      }


      // -----------------------------------------------
      // TTE MOVING AVERAGE
      // -----------------------------------------------

      if (
        averageDischarge_A ==
        0.0
      ) {

        averageDischarge_A =
          current_A;
      }

      else {

        averageDischarge_A =
          (
            TTE_ALPHA
            *
            current_A
          )
          +
          (
            (
              1.0
              -
              TTE_ALPHA
            )
            *
            averageDischarge_A
          );
      }
    }


    // =================================================
    // CHARGE
    // =================================================

    if (
      current_A <
      0.0
    ) {

      float chargeCurrent =
        -current_A;

      if (
        chargeCurrent >
        peakCharge_A
      ) {

        peakCharge_A =
          chargeCurrent;
      }
    }


    // =================================================
    // AMP HOURS
    // =================================================

    float elapsedHours =
      elapsedMs
      /
      3600000.0;

    float deltaAh =
      current_A
      *
      elapsedHours;


    // Positive = discharge

    if (
      current_A >
      0.0
    ) {

      sessionUsedAh +=
        deltaAh;
    }


    // Negative = charge

    else if (
      current_A <
      0.0
    ) {

      sessionChargedAh +=
        -deltaAh;
    }


    // =================================================
    // SOC
    // =================================================

    if (
      socSynchronized
    ) {

      // Positive current removes capacity.
      // Negative current adds capacity.

      remainingAh -=
        deltaAh;

      remainingAh =
        constrain(
          remainingAh,
          0.0,
          BATTERY_CAPACITY_AH
        );
    }
  }


  // ===================================================
  // POWER
  // ===================================================

  power_W =
    batteryVoltage
    *
    filteredCurrent_A;


  // ===================================================
  // SAVE SOC
  // ===================================================

  if (
    socSynchronized
    &&
    (
      now -
      lastSaveMillis
      >=
      SAVE_INTERVAL_MS
    )
  ) {

    saveBatteryState();
  }
}


